import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 29 The hovercraft","description":"学习 使役与许可结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 29 The hovercraft","description":"学习 使役与许可结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 使役与许可结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 28 Patients and doctors","link":"/life/english/new-concept/book-4/unit-04/lesson-028"},"next":{"text":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","link":"/life/english/new-concept/book-4/unit-04/lesson-030"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 28 Patients and doctors","link":"/life/english/new-concept/book-4/unit-04/lesson-028"},"next":{"text":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","link":"/life/english/new-concept/book-4/unit-04/lesson-030"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-029.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-029.md"}'),l={name:"life/english/new-concept/book-4/unit-04/lesson-029.md"};function i(r,e,s,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-29-the-hovercraft" tabindex="-1">第四册：流利英语 · Lesson 29 The hovercraft <a class="header-anchor" href="#第四册-流利英语-·-lesson-29-the-hovercraft" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 29 The hovercraft&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以气垫船为装置说明场景，练习从部件、动作到功能的解释顺序。不要只堆积技术名词，应让没有相关背景的读者理解哪个部件作用于哪个对象。重点用 enable、allow 与 make 描述功能，并分清主语是设计、设备还是操作人员。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>cushion</td><td>/ˈkʊʃən/</td><td>n.</td><td>垫层</td><td>a cushion of air</td></tr><tr><td>surface</td><td>/ˈsɜːfɪs/</td><td>n.</td><td>表面</td><td>a smooth surface</td></tr><tr><td>propulsion</td><td>/prəˈpʌlʃən/</td><td>n.</td><td>推进</td><td>a propulsion system</td></tr><tr><td>friction</td><td>/ˈfrɪkʃən/</td><td>n.</td><td>摩擦</td><td>reduce friction</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>allow for — 考虑到；为某因素留余地</li><li>move across — 横越某表面</li></ul><h2 id="语法讲解-使役与许可结构" tabindex="-1">语法讲解：使役与许可结构 <a class="header-anchor" href="#语法讲解-使役与许可结构" aria-label="Permalink to &quot;语法讲解：使役与许可结构&quot;">​</a></h2><p>enable/allow + 宾语 + to do 表示使某人能够或允许某人做事；make + 宾语 + 动词原形表示使某人做事，主动结构不带 to。被动 be made to do 则恢复 to。The cushion allows the craft to move… 描述功能，不能写 allows the craft move。enable 强调能力或条件，allow 可表许可也可表条件允许；实际语义要结合装置或人的语境判断。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The air cushion allows the model to move across the smooth floor.</p></blockquote><p>气垫使这个模型能够在光滑地板上移动。</p><p>allows + the model + to move 是宾语加不定式补足语；air cushion 为提供条件的主语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>allows the model move 缺少 to；不要把 allow 的结构误套成 make 的结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>交替读 allows it to move 与 makes it move；录音确认 allow 后的 to 没被误删，make 后没有多加 to。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A thin layer of air allows the model to slide over the table. A small fan provides the airflow. This demonstration illustrates one principle rather than the full design of a real craft.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句向中学生解释一个纸模型，说明条件、动作和演示边界。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>功能结构清晰，最后一句说明模型只展示部分原理，避免过度类比。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：The guide enabled visitors ___ understand the diagram.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> enable + 宾语 + to do。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>选择：The fan made the paper move / to move。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> move</p><p><strong>解析：</strong> 主动 make 后接不带 to 不定式。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 They made us repeat the test. 改为被动。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We were made to repeat the test.</p><p><strong>解析：</strong> make 的被动结构恢复 to。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：使役与许可结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-028">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-030">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
